const axe = require('axe-core');
const fs = require('fs');
const path = require('path');

(async () => {
  let browser;
  try {
    browser = await chromium.launch();
    const page = await browser.newPage();

    // We need to serve the file using a file url or set content
    const htmlContent = fs.readFileSync(path.resolve('index.html'), 'utf8');
    await page.setContent(htmlContent, { waitUntil: 'load' });

    // Wait for Babel and React to render
    await page.waitForSelector('form');

    // Evaluate if the form actually rendered inputs
    const formHtml = await page.evaluate(() => document.body.innerHTML);
    // console.log("Rendered HTML length:", formHtml.length);

    await page.click('button[type="submit"]');

    // Inject axe-core
    await page.addScriptTag({ path: require.resolve('axe-core') });

    // Run axe
    const results = await page.evaluate(async () => {
      return await window.axe.run();
    });

    const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
    const bp = results.violations.filter(v => v.tags.includes('best-practice'));

