      bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
    }));

    if (wcag.length > 0) process.exit(1);
    process.exit(0);
  } catch (error) {
    console.error(error.message);
    process.exit(2);
  } finally {
    if (browser) await browser.close();
  }
